//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//
scwin.vScrenID = "ULDCOM00007.xml";
// 전역 변수 선언
scwin.gJongcode = ""; //업종코드
scwin.gUpjongJongmok = ""; //업종에 따른 종목
scwin.gFilterType = ""; //"S":종목검색버튼,"O"
scwin.gJongName = ""; //종목명
scwin.ssMarket = "N"; //종목콤보확인
scwin.stat = "";
scwin.gListStatCd = "";
scwin.skw = "";

//----W-Craft WebSquare 변환 확인: Filter----//

//scwin.tpcd = $c.frame.path("../").js_com_market;
//scwin.tpcd = frame.Provider("../").js_com_market; //세션의 시장구분
scwin.tpcd = $c.session.info("js_market");  //임시

// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function() {
    scwin.stat = $c.frame.path("../").js_listStatCd; //상장상태여부

    if (scwin.stat === undefined) {
        scwin.stat = "";
    } else {
        scwin.gListStatCd = scwin.stat;
        if (scwin.gListStatCd === "Y") {
            combo_stat.setValue('Y'); // TODO Stage2: bindColVal 세터 검토
            combo_stat.setDisabled(true);
        }
    }
    ////$c.cm.PanelToGroupBox_01(panel_1);  //라운드CSS 삭제
    ////$c.cm.PanelToGroupBox_02(panel_2);  //라운드CSS 삭제
    const sbmOptions = {
        id : "sbm_dts_jongmok",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_jongmok=body.content",
        submitDoneHandler : scwin.dts_jongmok_OnLoadCompleted,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


    const sbmOptions2 = {
        id : "sbm_MxDataSet_code1",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_code1=body.content",
        submitDoneHandler : scwin.MxDataSet_code1_OnLoadCompleted,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions2);


    const sbmOptions3 = {
        id : "sbm_MxDataSet_code2",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_code2=body.content",
        submitDoneHandler : scwin.sbm_MxDataSet_code2_submitdone, // TODO Stage2: submitdone 핸들러 미정의 (sbm_MxDataSet_code2)
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions3);


    scwin.code1Sync();
    scwin.listSync();
};

scwin.onpageunload = function() {
};

// WebSquare 컴포넌트 이벤트 함수
scwin.dts_jongmok_OnLoadCompleted = function(e) {
};

scwin.MxDataSet_code1_OnLoadCompleted = function(e) {
    scwin.marketSetCombo();
};

//----W-Craft WebSquare 변환 확인: Filter----//
scwin.MxDataSet_code1_OnFilter = function(row) {
    // TODO Stage2: 필터 재구현 (setColumnFilter); 0-based 검토
    if (dts_jongmok.getCellData(row, "SPOT_ISU_TRD_MKT_TP_CD") === scwin.gJongcode) return true;

    else return false;
};

scwin.grd_jongmok_OnKeyPress = function(kcode) {
    if (kcode === 13) {
        scwin.Confirm();
    }
};

scwin.grd_jongmok_OnDblClick = function(row, colid) {
    scwin.Confirm();
};

scwin.img_search_onclick = function(e) {
    scwin.JongmokName(txb_jongmokName.value);
};

scwin.txb_jongmokName_onkeydown = function(e) {
    if (e.keyCode === 13) {
        //JongmokName(window.event.keyCode);
        scwin.JongmokSearch();
    }
};

scwin.combo_market_onselchange = function(info) {
    if (scwin.ssMarket === "Y") {
        txb_jongmokName.setValue("");
        scwin.skw = "";
        scwin.tpcd = MxDataSet_code1.getCellData(combo_market.getSelectedIndex(), "CD_VAL"); // TODO Stage2: 0-based 검토
        scwin.listSync();
    }
};

scwin.combo_stat_onselchange = function(info) {
    txb_jongmokName.setValue("");
    scwin.skw = "";

    scwin.stat = combo_stat.getValue(); // TODO Stage2: ValueOfIndex(bindcolumn Column2)→getValue 검토
    if (scwin.stat === '0') {
        scwin.stat = "";
    }
    scwin.listSync();
};

//----W-Craft WebSquare 변환 확인: Filter----//
scwin.dts_jongmok_OnFilter = function(row) {
    if (scwin.skw !== "") {
        let f1 = (dts_jongmok.getCellData(row, "COM_ABBRV")).toUpperCase(); // TODO Stage2: 0-based 검토 / 필터 재구현(setColumnFilter)
        let f2 = (dts_jongmok.getCellData(row, "OLD_COM_ABBRV")).toUpperCase();
        if (f1.indexOf(scwin.skw) !== -1) {
            return true;
        } else if (f2.indexOf(scwin.skw) !== -1) {
            return true;
        } else {
            return false;
        }
    } else {
        return true;
    }
};

