// 일반 함수
 //세션의 시장구분
scwin.listSync = function() {
    ////var url = "/isurcd.do?method=searchIsurCd&inputMessageId=isurcd&outputMessageId=isurcd" + "&LIST_STAT_CD=" + scwin.stat + "&SPOT_ISU_TRD_MKT_TP_CD=" + scwin.tpcd + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_jongmok",
        action : "/ui/dsclsrch/data/isurCode.jsp",
        ref : "",
        target : "dts_jongmok=body.content",
        submitDoneHandler : scwin.dts_jongmok_OnLoadCompleted,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);
};

/********************************************** 
 * 함수명   : Jongmok()
 * 설명       : 가나다라..검색
 ***********************************************/
scwin.Jongmok = function(prevval, nextval) {
    txb_jongmokName.setValue("");
    scwin.skw = "";

    // TODO Stage2: 필터 재구현 (setColumnFilter)
    //dts_jongmok.UseFilter = "true";
    //dts_jongmok.Filter();
    dts_jongmok.sort("COM_ABBRV", 0);
    let cnt = 0;
    for (let i = 1; i <= dts_jongmok.getRowCount(); i++) { // TODO Stage2: 0-based 검토
        let name = dts_jongmok.getCellData(i, "COM_ABBRV").substring(0, 1);
        if (name >= prevval && name < nextval) {
            cnt = i;
            break;
        }
    }
    // TODO Stage2: RowPosition 세터 검토 (setFocusedCell)
    //dts_jongmok.Rowposition = cnt + 11;
    //dts_jongmok.Rowposition = cnt;
    grd_jongmok.focus();
};

/********************************************** 
 * 함수명   : JongmokName()
 * 설명       : 종목명검색
 ***********************************************/
scwin.JongmokName = function(keyCode) {
    //if(keyCode==13) on_close();
    dts_jongmok.sort("COM_ABBRV", 0);
    let cnt = 0;
    const len = txb_jongmokName.getValue().length;
    const txtVal = txb_jongmokName.getValue().toUpperCase();
    for (let i = 1; i <= dts_jongmok.getRowCount(); i++) { // TODO Stage2: 0-based 검토
        let name = dts_jongmok.getCellData(i, "COM_ABBRV").substring(0, len).toUpperCase();
        if (txtVal <= name) {
            cnt = i;
            break;
        }
    }
    // TODO Stage2: RowPosition 세터 검토 (setFocusedCell)
    //dts_jongmok.Rowposition = cnt + 11;
    //dts_jongmok.Rowposition = cnt;
};

/********************************************** 
 * 함수명   : JongmokSearch()
 * 설명       : 종목명검색
 ***********************************************/
scwin.JongmokSearch = function() {
    scwin.skw = (txb_jongmokName.getValue()).toUpperCase();

    //----W-Craft WebSquare 변환 확인: Filter----//
    ////dts_jongmok.UseFilter = "true";

    //----W-Craft WebSquare 변환 확인: Filter----//
    ////dts_jongmok.Filter();
    ////dts_jongmok.Rowposition = 1;
};

/********************************************** 
 * 함수명   : Confirm()
 * 설명       : 부모창으로 종목코드 전달
 ***********************************************/
scwin.Confirm = async function() {
    //frame.Provider("../").종목코드id
    const pJongCode = dts_jongmok.getCellData(dts_jongmok.getRowPosition(), "ISUR_CD"); // TODO Stage2: 0-based 검토
    const pJongNm = dts_jongmok.getCellData(dts_jongmok.getRowPosition(), "COM_ABBRV");
    const ld_mkt_tp_cd = dts_jongmok.getCellData(dts_jongmok.getRowPosition(), "SPOT_ISU_TRD_MKT_TP_CD");
    $c.frame.path("../").isurSearch_Rtn(pJongCode, pJongNm, ld_mkt_tp_cd);

    await $c.win.closePopup();
};

scwin.code1Sync = function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_code1",
        action : "/tbmccdval.do",
        ref : "",
        target : "MxDataSet_code1=body.content",
        submitDoneHandler : scwin.MxDataSet_code1_OnLoadCompleted,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


    const sbmOptions2 = {
        id : "sbm_MxDataSet_code2",
        action : "/tbmccdval.do",
        ref : "",
        target : "MxDataSet_code2=body.content",
        submitDoneHandler : scwin.sbm_MxDataSet_code2_submitdone, // TODO Stage2: submitdone 핸들러 미정의 (sbm_MxDataSet_code2)
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions2);


};

scwin.marketSetCombo = function() {
    let cIndex;
    let name;
    if (scwin.tpcd !== "") {
        for (let i = 1; i <= MxDataSet_code1.getRowCount(); i++) { // TODO Stage2: 0-based 검토
            name = MxDataSet_code1.getCellData(i, "CD_VAL");
            if (name === scwin.tpcd) {
                cIndex = i - 1;
                break;
            }
        }
        combo_market.setSelectedIndex(cIndex);
    }
    if (scwin.tpcd === "1" || scwin.tpcd === "2") {
        combo_market.setDisabled(true);
    }
    scwin.ssMarket = "Y";
};
